def column_totals(rows):
    if not rows:
        return []
    num_cols = len(rows[0])
    totals = []
    for col in range(num_cols):
        col_total = 0
        has_numeric = False
        for row in rows:
            cell = row[col]
            if isinstance(cell, (int, float)):
                col_total += cell
                has_numeric = True
        if has_numeric:
            totals.append(col_total)
        else:
            totals.append("")
    return totals

